@startuml

class Airline {
  + ID
}

class Flight {
  + ID
  + departureTime
  + arrivalTime
}

class Airport {
  + ID
}

class Aircraft {
  + state
  + position
}

class AircraftType {
  + type
}

class Pilot {
  + experienceLevel
}

class RoleRequirement {
  + role
  + minLevel
}

class Role {
  + roleName
}

Airline "1" -- "*" Flight : operates
Airline "1" *-- "*" Aircraft : owns
Flight "*" -- "1" Airport : departure airport
Flight "*" -- "1" Airport : arrival airport
Flight "*" -- "1" Pilot : captain
Flight "*" -- "1" Pilot : co-pilot
Flight "*" -- "1" Aircraft : uses
Aircraft "*" -- "1" AircraftType : is of type
Pilot "*" -- "1" AircraftType : is required for

@enduml

